#[derive(Debug)]
struct EncodeState { .. }

impl EncodeBody<()> { .. }

impl EncodeState { .. }

impl<S> Body for EncodeBody<S>
where
    S: Stream<Item = Result<Bytes, Status>>,
{ .. }

