/// Owned future returned by [`ProstEncoder`] for one message encode.
#[derive(Debug)]
pub struct ProstEncode {
    result: Option<Result<EncodeBuffer, EncodeError>>,
}

impl ProstEncode {
    #[inline]
    fn new<T: Message>(item: T, mut buf: EncodeBuffer) -> Self {
        let result = {
            let mut encode_buf = buf.as_encode_buf();
            item.encode(&mut encode_buf)
        };

        Self {
            result: Some(result.map(|()| buf)),
        }
    }
}

impl Future for ProstEncode {
    type Output = Result<EncodeBuffer, Status>;

    fn poll(mut self: Pin<&mut Self>, _cx: &mut Context<'_>) -> Poll<Self::Output> {
        let result = self
            .result
            .take()
            .expect("ProstEncode polled after completion");
        Poll::Ready(match result {
            Ok(buf) => Ok(buf),
            Err(_error) => {
                panic!("Message only errors if not enough space")
            }
        })
    }
}

impl<T> ProstEncoder<T> {
    /// Get a new encoder with explicit buffer settings.
    pub fn new(buffer_settings: BufferSettings) -> Self {
        Self {
            _pd: PhantomData,
            buffer_settings,
