580:        source: &[u8],
581:        buf: &mut EncodeBuffer,
582:        cx: &mut Context<'_>,
583:    ) -> Poll<Result<(), Status>> {
584:        // SAFETY: This method never moves fields out of the pinned state. It
585:        // only mutates scalar state and borrows the owned descriptor,
586:        // completion record, and encode buffer in place.
587:        let this = unsafe { self.as_mut().get_unchecked_mut() };
588:
589:        if !this.submitted {
590:            let len = source.len();
591:            let mut dst = buf.as_encode_buf();
592:            // SAFETY: The pending state has exclusive access to the encode
593:            // buffer through the poll call until completion. The matching
594:            // advance happens exactly once after DSA reports success.
595:            let dst_ptr = unsafe { dst.reserve_uninit_slice_for_pending(len) };
596:            touch_pages_for_dsa(source.as_ptr(), dst_ptr, len);
597:
598:            let retry = DsaMemmoveRetry::new(source.as_ptr(), dst_ptr, len);
599:            submit_retry(
600:                &this.work_queue,
601:                &mut this.desc,
602:                &mut this.completion,
603:                &retry,
604:            )?;
605:            this.retry = Some(retry);
606:            this.source = source.as_ptr();
607:            this.source_len = len;
608:            this.dst = dst_ptr;
609:            this.dst_len = len;
610:            this.submitted = true;
611:        } else {
612:            debug_assert_eq!(this.source, source.as_ptr());
613:            debug_assert_eq!(this.source_len, source.len());
614:        }
615:
616:        if this.completion.status() == DsaCompletionStatus::None.as_u8() {
617:            cx.waker().wake_by_ref();
618:            return Poll::Pending;
619:        }
620:
621:        let retry = this.retry.as_mut().expect("pending retry state available");
622:        match retry.handle_completion(this.completion, &this.work_queue.config.device_path) {
623:            Ok(DsaRetryAction::Complete) => {
624:                this.completed = true;
