630:                }
631:                Poll::Ready(Ok(()))
632:            }
633:            Ok(DsaRetryAction::Retry) => {
634:                submit_retry(
635:                    &this.work_queue,
636:                    &mut this.desc,
637:                    &mut this.completion,
638:                    retry,
