                if state.phase() == 3 {
                    if !skip_val {
                        #val_start
                    } else {
                        state.set_phase(5);
                    }
                }
                if state.phase() == 4 {
                    #val_pending
                }

                state.set_index(state.index() + 1);
                state.set_phase(0);
                __prost_entry_index += 1;
            }

            state.advance_field();
        }
